"""R12 report tables, generated from the persisted records only (counts, flags, hashes; no target, prediction or amplitude value):
  a2_gate.md         the five must-hold items per harness pair (rehearsal/checks/a2_checks.json)
  a3_control.md      the EW0207 environment control (rehearsal/provenance/environment_control_*.json)
  c1_preconditions.md the §C1 preconditions (rehearsal/checks/c1_preconditions.json)
  c2_build.md        the phase4 build job outcome (logs/phase4_build_<job>.out: refusal / per-pair counts with the amplitude REDACTED)
  files_r12.md       sha256 of the delivered files
Written to R12/tables/."""
import glob, json, os, re, sys
import r12_common as R12
P4 = R12.P4; HERE = os.path.dirname(os.path.abspath(__file__)); TAB = os.path.join(os.path.dirname(HERE), "tables"); os.makedirs(TAB, exist_ok=True)
def w(name, lines): open(os.path.join(TAB, name), "w").write("\n".join(lines) + "\n"); print("wrote", name)
def b(x): return "**True**" if x else "**False**"
if __name__ == "__main__":
    # A2
    a = json.load(open(f"{R12.ROOT}/checks/a2_checks.json")); L = [f"<!-- generated by report_tables_r12.py from rehearsal/checks/a2_checks.json (check_a2_r12.py); harness {a['gate']['harness_sha256'][:16]}… -->",
         "| harness row | status | 1. build complete: tiles v1 → v1.1 (frozen v1.1) / blocks kept / fields / A_fine finite on tiles with joint px / tiles_int rows / D₁ px (expected) / interior tiles / blocks / fallback tiles / blocks / view(B8) / feature rows (k, lr_native) / P-V1 inputs x shape, finite, cond finite | 2. f_hi = k hr_res / lr_native (recorded) < 0.45; equals record | 3. s_lr finite / tiles; lr_px formula / R06 | 4. predictions finite: s_lr / GBT_ship / P-V1 of n | 5. F_hr finite fraction: harness / frozen (joint-valid: harness / frozen); masks identical | all five |", "|---|---|---|---|---|---|---|"]
    for pid, r in a["pairs"].items():
        i1, i2, i3, i4, i5 = r["item1"], r["item2"], r["item3"], r["item4"], r["item5"]; pv = i1["pv1_inputs"]
        L.append(f"| {r['label']} {pid} | {r['status']} | {i1['n_tiles_v1']} → {i1['n_tiles_v1_1']} ({i1['frozen_n_tiles_v1_1']}; ids equal {i1['tile_ids_equal_frozen']}) / {i1['n_blocks_kept']} / {all(i1['fields'].values())} / {i1['A_fine_finite_on_tiles_with_joint_px']['n_A_fine_finite']} of {i1['A_fine_finite_on_tiles_with_joint_px']['n_tiles_with_joint_px']} / {i1['tiles_int_rows']} / **{i1['D1_px']}** ({i1['D1_expected']}) / {i1['interior_D1']['n_tiles']} / {i1['interior_D1']['n_blocks']} / {i1['fallback_D1']['n_tiles_A_fine_int_defined']} / {i1['fallback_D1']['n_blocks']} / {i1['view_B8']} / {i1['n_feature_rows']} (k {i1['feature_meta']['k']}, lr {i1['feature_meta']['lr_native']}) / {pv['x_shape']}, {pv['x_finite']}, {pv['cond_finite']} → {b(i1['passed'])} | {i2['f_hi_formula']:.4f} ({i2['f_hi_recorded_tiles_v1'][0]:.4f}) < {i2['clip']}: {i2['below_clip']}; {i2['equals_record']} → {b(i2['passed'])} | {i3['n_s_lr_finite']} / {i3['n_tiles']} ({i3['frac']:.4f}); {i3['lr_px_formula']} / {i3['lr_px_r06']} → {b(i3['passed'])} | {i4.get('s_lr_finite')} / {i4.get('GBT_ship_finite')} / {i4.get('P-V1_finite')} of {i4.get('n_pred_tiles')} → {b(i4['passed'])} | {i5['finite_frac_all_cells']['harness']:.4f} / {i5['finite_frac_all_cells']['frozen']:.4f} ({i5['finite_frac_joint_valid_cells']['harness']:.4f} / {i5['finite_frac_joint_valid_cells']['frozen']:.4f}); joint {i5['joint_mask_identical']}, finite {i5['finite_mask_identical']} → {b(i5['passed'])} | {b(r['all_passed'])} |")
    for k, v in a["logs"].items(): L.append(f"| log `{k}` | lines {v.get('n_lines')} | warning / traceback / error lines: **{v.get('n_hits')}** {('— ' + '; '.join(v['hits'][:6])) if v.get('n_hits') else ''} | | | | | |")
    L.append(f"| **gate** | | all five items on both rows: {b(a['gate']['all_items_passed'])} | harness logs clean: {b(a['gate']['logs_clean'])} | | | | |")
    w("a2_gate.md", L)
    # A3
    L = ["<!-- generated by report_tables_r12.py from rehearsal/provenance/environment_control_*.json (phase4_predict.py §A5, run inside the harness prediction) -->", "| job | node | CPU | s_lr identical | GBT_ship max \\|Δ\\| (m) | P-V1 seed-averaged max \\|Δ log₁₀\\| | per seed | passed | seconds |", "|---|---|---|---|---|---|---|---|---|"]
    for p in sorted(glob.glob(f"{R12.ROOT}/provenance/environment_control_*.json")):
        c = json.load(open(p))["environment_control"]; L.append(f"| {json.load(open(p)).get('slurm_job')} | {c['node']} | {c['cpu']} | {c['s_lr_identical']} | {c['gbt_max_abs_diff_m']:.2e} | {c['pv1_seedavg_max_abs_diff_log10']:.2e} | {', '.join(f'{s}: {v:.1e}' for s, v in c['pv1_per_seed_max_abs_diff_log10'].items())} | {b(c['passed'])} | {c['seconds']:.0f} |")
    L.append(f"| tolerances | | | identical | ≤ {P4.CTRL_TOL['gbt_m']:.0e} | ≤ {P4.CTRL_TOL['pv1_log10']:.0e} | | | |"); w("a3_control.md", L)
    # C1
    c = json.load(open(f"{R12.ROOT}/checks/c1_preconditions.json")); s1, p1, d2, sc, s4, r4, g5 = c["1_signoff"], c["1_prereg_v2"], c["2_deviation"], c["3_scripts"], c["4_supplement"], c["4_completion_record"], c["5_guard"]
    L = [f"<!-- generated by report_tables_r12.py from rehearsal/checks/c1_preconditions.json (preconditions_r12.py at git {c['git_head'][:8]}) -->", "| precondition | evidence | passed |", "|---|---|---|",
         f"| 1 sign-off committed, holds the v2 sha256; v2 at its tag | `SIGNOFF_phase4_prereg_v2.md` sha256 `{s1['sha256'][:16]}…`, commit `{s1['last_commit'][:8]}`, clean {s1['clean']}, holds `{'9795db3b'}…` {s1['holds_v2_sha']}; `PREREG_phase4_v2.md` on disk `{p1['sha256_on_disk'][:16]}…` = at tag `phase4-prereg-v2` (commit `{p1['tag_commit'][:8]}`) `{p1['sha256_at_tag'][:16]}…`, clean {p1['clean']} | {b(c['1_passed'])} |",
         f"| 2 deviation note committed and clean | `R11/DEVIATION_phase4_01.md` sha256 `{d2['sha256'][:16]}…` (expected `{d2['expected'][:16]}…`), last commit `{d2['last_commit'][:8]}` (expected `{d2['expected_commit'][:8]}`), clean {d2['clean']} | {b(c['2_passed'])} |",
         f"| 3 the five scripts match the B6 table | " + "; ".join(f"`{k}` `{v['on_disk'][:12]}…` = B6 {v['equal']}, clean {v['clean']}" for k, v in sc.items()) + f" | {b(c['3_passed'])} |",
         f"| 4 supplement and completion run record match §B; both sha256 in the ledger | supplement `{s4['sha256'][:16]}…` (= §B {s4['sha256'] == s4['expected']}; in ledger {s4['in_ledger']}); completion record `{r4['sha256'][:16]}…` (= §B {r4['sha256'] == r4['expected']}; in ledger {r4['in_ledger']}) | {b(c['4_passed'])} |",
         f"| 5 guard self-test | {g5['blocked']} of {g5['probes']} probes blocked ({len(g5['readers'])} readers, {len(g5['rows'])} sealed paths) | {b(c['5_passed'])} |", f"| **all five** | | {b(c['all_passed'])} |",
         f"| (challenge evidence) §A2.2 acquisition run-record lock, called with the supplement's sha256 | accepted {c['acq_lock']['accepted']}; completion record: status `{c['acq_lock']['completion_record_fields']['status']}`, mode `{c['acq_lock']['completion_record_fields']['mode']}`, supplement_sha256 matches, top-level freeze_record_sha256 `331c94f0…`, lock keys {c['acq_lock']['completion_record_fields']['lock_keys']}; `locks.lock2_freeze_record` = {c['acq_lock']['completion_record_fields']['locks_lock2_freeze_record']}; `locks.lock2_frozen_code.freeze_record_sha256` = `{(c['acq_lock']['completion_record_fields']['locks_lock2_frozen_code'] or {}).get('freeze_record_sha256', '')[:16]}…` | lock refuses |"]
    w("c1_preconditions.md", L)
    # C2 build job log (amplitude redacted)
    L = ["<!-- generated by report_tables_r12.py from logs/phase4_build_*.out / .err (the amplitude printed by phase4_build.py is REDACTED here) -->", "| job | node / CPU | outcome | message (first 400 characters) |", "|---|---|---|---|"]
    for p in sorted(glob.glob(f"{R12.LOGS}/phase4_build_*.out")):
        job = re.search(r"_(\d+)\.out$", p).group(1); txt = open(p, errors="replace").read(); err = open(p[:-4] + ".err", errors="replace").read() if os.path.exists(p[:-4] + ".err") else ""
        node = re.search(r"=== .* (sh\S+) job=", txt); cpu = re.search(r"model name\s*:\s*(.*)", txt); ref = re.search(r"(phase4_common\.Refusal: .*|Refusal: .*)", err + txt); rc = re.search(r"rc=(\d+)", txt)
        built = [re.sub(r"amplitude [0-9.eE+-]+ m", "amplitude [redacted]", l.strip()) for l in txt.splitlines() if l.strip().startswith("built ") or "not scorable" in l]
        L.append(f"| {job} | {node.group(1) if node else '?'} / {cpu.group(1).strip() if cpu else '?'} | {'stopped at a lock (Refusal), rc ' + (rc.group(1) if rc else '?') if ref else ('completed, rc ' + (rc.group(1) if rc else '?'))} | {(ref.group(1)[:400] if ref else '; '.join(built)[:400]).replace('|', '\\|')} |")
    w("c2_build.md", L)
    # files
    files = [f"{R12.ROOT}/harness/harness_k32.parquet", f"{R12.ROOT}/harness/harness_record.json", f"{R12.ROOT}/checks/a2_checks.json", f"{R12.ROOT}/checks/c1_preconditions.json"] + sorted(glob.glob(f"{R12.ROOT}/provenance/*.json")) + sorted(glob.glob(f"{R12.ROOT}/predictions/*.parquet")) + sorted(glob.glob(f"{R12.ROOT}/build/*/pair_stats.json")) + sorted(glob.glob(f"{os.path.dirname(HERE)}/*.csv")) + sorted(glob.glob(f"{os.path.dirname(HERE)}/*.pdf"))
    L = ["<!-- generated by report_tables_r12.py -->", "| file | sha256 |", "|---|---|"] + [f"| `{f.replace('/scratch/users/scdobbs/grl_review/', '$SCRATCH/grl_review/')}` | `{P4.sha256_file(f)}` |" for f in files if os.path.exists(f)]
    w("files_r12.md", L)
